tool_input.command:
$sshPath = "/home/author\.ssh"

Write-Host "Removing old SSH keys..." -ForegroundColor Cyan

# Remove old key files
Remove-Item -Path "$sshPath\id_ed25519" -Force -ErrorAction Stop
Write-Host "✓ Removed id_ed25519"

Remove-Item -Path "$sshPath\id_ed25519.pub" -Force -ErrorAction Stop
Write-Host "✓ Removed id_ed25519.pub"

Write-Host "`n=== Checking for stale git credentials ===" -ForegroundColor Green
cmdkey /list 2>$null | Select-String 'git|github' -ErrorAction SilentlyContinue | ForEach-Object {
  Write-Host "Found: $_"
}

Write-Host "`nVerifying keys are removed..." -ForegroundColor Cyan
$remaining = Get-ChildItem -Path $sshPath -Force | Where-Object { $_.Name -match 'id_' }
if ($remaining) {
  Write-Host "Remaining keys: $($remaining.Name)"
} else {
  Write-Host "✓ No SSH key files remaining"
}
